import { defineConfig } from "vitest/config";

// One config for the image, at the image root, because the image is the unit CI
// addresses: `bundle-google-ci.yml`'s `google_sheets_unit` job does `npm ci` and
// `npm test` here, and the bundle's own `build-google` stage installs from this
// same manifest.
//
// The `include` names ONE directory on purpose. `vendor/gmail-shared`,
// `vendor/google-calendar-shared`, `vendor/google-docs-shared` and
// `vendor/mcp-elicitation` are copies — the first three from
// `pulsemcp/mcp-servers`, the fourth generated by `npm run elicitation:sync` — so
// a test written inside one of them is a merge conflict on the next re-vendor
// and belongs upstream. `vendor/google-sheets-shared` is not vendored from
// anywhere; it is strad's own server, and its suite is the only one here.
//
// The suites live in `test/`, outside that package's `include: ["src/**/*"]`, so
// `npm run build` emits exactly the `build/` it emitted before.
export default defineConfig({
  test: {
    environment: "node",
    include: ["vendor/google-sheets-shared/test/**/*.test.ts"],
    // The root's value, and every other tree's — `test/vitest-convergence.test.ts`
    // is what holds every config in the repo to it. The reason it is not 5s is
    // the same here as everywhere, arriving by a different route: this image is
    // NOT a leg of `ci.yml`'s `servers` matrix, it is gated by
    // `.github/workflows/bundle-google-ci.yml`, whose two jobs run on the same
    // one self-hosted box as every other workflow's — including that matrix's
    // thirteen concurrent legs. Vitest's default is a tighter bound than a
    // contended box can be held to.
    testTimeout: 20_000,
  },
});
